```c++
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string filename; // nom du fichier
    string search_word; // mot à rechercher
    int count = 0; // compteur de occurrences

    // demander le nom du fichier et le mot à rechercher
    cout << "Nom du fichier : ";
    cin >> filename;
    cout << "Mot à rechercher : ";
    cin >> search_word;

    // ouvrir le fichier
    ifstream file(filename);
    if (!file.is_open()) {
        cout << "Impossible d'ouvrir le fichier." << endl;
        return 1;
    }

    // lire le fichier ligne par ligne
    string line;
    while (getline(file, line)) {
        // convertir la ligne en minuscules pour une comparaison case-insensitive
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // compter le nombre d'occurrences du mot dans la ligne
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != string::npos) {
            count++;
            pos += search_word.length();
        }
    }

    // afficher le résultat
    cout << "Le mot \"" << search_word << "\" apparait " << count << " fois dans le fichier " << filename << endl;

    // fermer le fichier
    file.close();

    return 0;
}
